import{_ as o,o as t,c as a,a0 as n}from"./chunks/framework.DhH8_2wW.js";const p=JSON.parse('{"title":"Select a publishing engine","description":"","frontmatter":{},"headers":[],"relativePath":"markdown-publish--selecting-an-engine.md","filePath":"markdown-publish--selecting-an-engine.md"}'),i={name:"markdown-publish--selecting-an-engine.md"};function s(r,e,c,d,l,u){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="selecting-an-engine" tabindex="-1">Select a publishing engine <a class="header-anchor" href="#selecting-an-engine" aria-label="Permalink to &quot;Select a publishing engine {#selecting-an-engine}&quot;">​</a></h1><p>All four engines consume the same Markdown source, but their native tooling and configuration differ.</p><h2 id="mkdocs-engine" tabindex="-1">MkDocs <a class="header-anchor" href="#mkdocs-engine" aria-label="Permalink to &quot;MkDocs {#mkdocs-engine}&quot;">​</a></h2><p>MkDocs is the default and the lightest choice for this workflow. Install MkDocs and the theme or plugins required by your configuration. The backend accepts <code>command</code>, <code>strict</code>, <code>address</code>, and <code>output</code>. Strict builds are enabled by default.</p><p>A root <code>mkdocs.yml</code> is used directly. Another file named by <code>config</code> is normally inherited by a temporary configuration which supplies the assembled <code>docs_dir</code>, output directory, and navigation. Set <code>config_mode</code> to <code>direct</code> only when the authored file deliberately owns those paths as well.</p><h2 id="vitepress-engine" tabindex="-1">VitePress <a class="header-anchor" href="#vitepress-engine" aria-label="Permalink to &quot;VitePress {#vitepress-engine}&quot;">​</a></h2><p>VitePress runs in a temporary npm project. Set <code>npm</code> to another npm executable, <code>version</code> to a particular VitePress version, and <code>host</code>, <code>port</code>, or <code>output</code> as needed. An authored configuration named by <code>config</code> keeps its original location so its relative imports still work.</p><h2 id="docusaurus-engine" tabindex="-1">Docusaurus <a class="header-anchor" href="#docusaurus-engine" aria-label="Permalink to &quot;Docusaurus {#docusaurus-engine}&quot;">​</a></h2><p>Docusaurus also runs in a temporary npm project and accepts <code>npm</code>, <code>version</code>, <code>host</code>, <code>port</code>, and <code>output</code>. The generated project uses the classic preset, disables the blog, and places the documents at the site root.</p><h2 id="starlight-engine" tabindex="-1">Astro Starlight <a class="header-anchor" href="#starlight-engine" aria-label="Permalink to &quot;Astro Starlight {#starlight-engine}&quot;">​</a></h2><p>Starlight accepts <code>npm</code>, <code>astro_version</code>, <code>starlight_version</code>, <code>host</code>, <code>port</code>, and <code>output</code>. The generated project includes a Markdown link resolver so links to mirrored module pages become the routes that Starlight actually emits. An authored Astro configuration is wrapped to retain this resolver; if it supplies a Markdown processor, that processor must be unified.</p>',11)])])}const g=o(i,[["render",s]]);export{p as __pageData,g as default};
